//===- acc_addsub.cc --------------------------------------------*- C++ -*-===//
//
// fp32 accumulator add/sub capture kernel (GENERATED by tools/gen_acc_addsub_f32.py).
// Runs every form in FORMS over each of T tiles of one chunk; the chunk layout is
// A[T*16] fp32 followed by B[T*16] fp32.
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

#include <aie_api/aie.hpp>

#define T 16
#define NFORMS 20

extern "C" {

void acc_addsub(float *restrict in, float *restrict out) {
  float *inA = in;
  float *inB = in + T * 16;
  event0();
  for (int n = 0; n < T; n++) {
    aie::accum<accfloat, 16> a;
    a.from_vector(aie::load_v<16>(inA + n * 16));
    aie::accum<accfloat, 16> b;
    b.from_vector(aie::load_v<16>(inB + n * 16));
    float *o = out + n * NFORMS * 16;
    { aie::accum<accfloat, 16> r = a; aie::store_v(o + 0 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = b; aie::store_v(o + 1 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::add(a, b); aie::store_v(o + 2 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::sub(a, b); aie::store_v(o + 3 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negadd(a, b); aie::store_v(o + 4 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negsub(a, b); aie::store_v(o + 5 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::neg(a); aie::store_v(o + 6 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::add_conf(a, b, 1, 0, 0); aie::store_v(o + 7 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::add_conf(a, b, 0, 1, 0); aie::store_v(o + 8 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::add_conf(a, b, 0, 0, 1); aie::store_v(o + 9 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::add_conf(a, b, 0, 1, 1); aie::store_v(o + 10 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::sub_conf(a, b, 1, 0, 0); aie::store_v(o + 11 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::sub_conf(a, b, 0, 1, 0); aie::store_v(o + 12 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::sub_conf(a, b, 0, 0, 1); aie::store_v(o + 13 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negadd_conf(a, b, 0, 1, 0); aie::store_v(o + 14 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negadd_conf(a, b, 0, 0, 1); aie::store_v(o + 15 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negsub_conf(a, b, 0, 1, 0); aie::store_v(o + 16 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negsub_conf(a, b, 0, 0, 1); aie::store_v(o + 17 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::neg_conf(a, 1, 0); aie::store_v(o + 18 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::neg_conf(a, 0, 1); aie::store_v(o + 19 * 16, r.to_vector<float>()); }
  }
  event1();
}

} // extern "C"
